/*\n  # Liftpictures Sales Console - Base Schema\n\n  ## Tables Created\n\n  1. **profiles**\n     - Stores user profile information linked to Supabase auth\n     - Fields: id (uuid, references auth.users), email, role (admin|sales|viewer), created_at\n     - Used for role-based access control\n\n  2. **datasets**\n     - Tracks different dataset categories (e.g., "Zip-Lines", "Sommerrodelbahnen")\n     - Fields: id, name, description, created_at\n     - Allows organizing leads by business category\n\n  3. **countries**\n     - Master list of countries with activation status\n     - Fields: code (primary key, e.g., DE, AT), name, is_enabled, created_at\n     - Countries unlock when data is imported\n\n  4. **leads**\n     - Main table storing all attraction leads\n     - Contains contact info, social media, decision maker details, status tracking\n     - Fields include: source data, contact info, status, priority, follow-up dates, location\n     - Links to datasets and countries\n\n  5. **activities**\n     - Activity log for lead interactions\n     - Tracks calls, emails, LinkedIn messages, etc.\n     - Fields: type, outcome, notes, timestamps\n     - Links to leads and users\n\n  ## Security\n     - RLS enabled on all tables\n     - Users can only access data within their workspace\n     - Admin role can perform all operations\n     - Sales role can read/write most data\n     - Viewer role has read-only access\n*/\n\n-- Enable UUID extension if not already enabled\nCREATE EXTENSION IF NOT EXISTS "uuid-ossp";
\n\n-- ============================================\n-- PROFILES TABLE\n-- ============================================\nCREATE TABLE IF NOT EXISTS profiles (\n  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  email text NOT NULL,\n  role text NOT NULL DEFAULT 'sales' CHECK (role IN ('admin', 'sales', 'viewer')),\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
\n\n-- Profiles policies: users can read their own profile, admins can read all\nCREATE POLICY "Users can view own profile"\n  ON profiles FOR SELECT\n  TO authenticated\n  USING (auth.uid() = id);
\n\nCREATE POLICY "Users can update own profile"\n  ON profiles FOR UPDATE\n  TO authenticated\n  USING (auth.uid() = id)\n  WITH CHECK (auth.uid() = id);
\n\nCREATE POLICY "Admins can view all profiles"\n  ON profiles FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role = 'admin'\n    )\n  );
\n\nCREATE POLICY "Admins can update all profiles"\n  ON profiles FOR UPDATE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role = 'admin'\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role = 'admin'\n    )\n  );
\n\n-- ============================================\n-- DATASETS TABLE\n-- ============================================\nCREATE TABLE IF NOT EXISTS datasets (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  name text NOT NULL,\n  description text,\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE datasets ENABLE ROW LEVEL SECURITY;
\n\nCREATE POLICY "Authenticated users can view datasets"\n  ON datasets FOR SELECT\n  TO authenticated\n  USING (true);
\n\nCREATE POLICY "Admin and sales can create datasets"\n  ON datasets FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role IN ('admin', 'sales')\n    )\n  );
\n\nCREATE POLICY "Admin can update datasets"\n  ON datasets FOR UPDATE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role = 'admin'\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role = 'admin'\n    )\n  );
\n\nCREATE POLICY "Admin can delete datasets"\n  ON datasets FOR DELETE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role = 'admin'\n    )\n  );
\n\n-- ============================================\n-- COUNTRIES TABLE\n-- ============================================\nCREATE TABLE IF NOT EXISTS countries (\n  code text PRIMARY KEY,\n  name text NOT NULL,\n  is_enabled boolean DEFAULT false,\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE countries ENABLE ROW LEVEL SECURITY;
\n\nCREATE POLICY "Authenticated users can view countries"\n  ON countries FOR SELECT\n  TO authenticated\n  USING (true);
\n\nCREATE POLICY "Admin and sales can update countries"\n  ON countries FOR UPDATE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role IN ('admin', 'sales')\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role IN ('admin', 'sales')\n    )\n  );
\n\n-- ============================================\n-- LEADS TABLE\n-- ============================================\nCREATE TABLE IF NOT EXISTS leads (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  dataset_id uuid REFERENCES datasets(id) ON DELETE CASCADE,\n  country_code text REFERENCES countries(code) ON DELETE CASCADE,\n  attraction_type text NOT NULL,\n  title text NOT NULL,\n  source_placeUrl text,\n  source_imgUrl text,\n  rating numeric,\n  reviewCount integer,\n  category_raw text,\n  address text,\n  plusCode text,\n  website text,\n  phoneNumber text,\n  currentStatus_raw text,\n  isClaimed boolean,\n  opening_hours jsonb,\n  linkedin_company text,\n  linkedin_person text,\n  instagram text,\n  facebook text,\n  decision_maker_name text,\n  decision_maker_role text,\n  email_primary text,\n  email_secondary text,\n  icebreaker text,\n  notes text,\n  priority text DEFAULT 'C' CHECK (priority IN ('A', 'B', 'C')),\n  status text DEFAULT 'new' CHECK (status IN ('new', 'contacted', 'followup', 'meeting', 'interested', 'won', 'lost', 'not_fit')),\n  owner_user_id uuid REFERENCES profiles(id) ON DELETE SET NULL,\n  first_contacted_at timestamptz,\n  last_contacted_at timestamptz,\n  next_followup_at timestamptz,\n  meeting_date timestamptz,\n  lat numeric,\n  lng numeric,\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE leads ENABLE ROW LEVEL SECURITY;
\n\nCREATE POLICY "Authenticated users can view leads"\n  ON leads FOR SELECT\n  TO authenticated\n  USING (true);
\n\nCREATE POLICY "Admin and sales can create leads"\n  ON leads FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role IN ('admin', 'sales')\n    )\n  );
\n\nCREATE POLICY "Admin and sales can update leads"\n  ON leads FOR UPDATE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role IN ('admin', 'sales')\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role IN ('admin', 'sales')\n    )\n  );
\n\nCREATE POLICY "Admin can delete leads"\n  ON leads FOR DELETE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role = 'admin'\n    )\n  );
\n\n-- ============================================\n-- ACTIVITIES TABLE\n-- ============================================\nCREATE TABLE IF NOT EXISTS activities (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  lead_id uuid REFERENCES leads(id) ON DELETE CASCADE,\n  type text NOT NULL CHECK (type IN ('call', 'email', 'linkedin', 'letter', 'other')),\n  outcome text CHECK (outcome IN ('no_answer', 'left_voicemail', 'sent', 'replied', 'meeting_set', 'not_interested', 'interested', 'won', 'lost', 'other')),\n  activity_at timestamptz DEFAULT now(),\n  note text,\n  created_by uuid REFERENCES profiles(id) ON DELETE SET NULL,\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE activities ENABLE ROW LEVEL SECURITY;
\n\nCREATE POLICY "Authenticated users can view activities"\n  ON activities FOR SELECT\n  TO authenticated\n  USING (true);
\n\nCREATE POLICY "Admin and sales can create activities"\n  ON activities FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role IN ('admin', 'sales')\n    )\n  );
\n\nCREATE POLICY "Users can update own activities"\n  ON activities FOR UPDATE\n  TO authenticated\n  USING (created_by = auth.uid())\n  WITH CHECK (created_by = auth.uid());
\n\nCREATE POLICY "Admin can delete activities"\n  ON activities FOR DELETE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles\n      WHERE profiles.id = auth.uid()\n      AND profiles.role = 'admin'\n    )\n  );
\n\n-- Create indexes for performance\nCREATE INDEX IF NOT EXISTS idx_leads_country_code ON leads(country_code);
\nCREATE INDEX IF NOT EXISTS idx_leads_dataset_id ON leads(dataset_id);
\nCREATE INDEX IF NOT EXISTS idx_leads_attraction_type ON leads(attraction_type);
\nCREATE INDEX IF NOT EXISTS idx_leads_status ON leads(status);
\nCREATE INDEX IF NOT EXISTS idx_leads_next_followup_at ON leads(next_followup_at);
\nCREATE INDEX IF NOT EXISTS idx_leads_last_contacted_at ON leads(last_contacted_at);
\nCREATE INDEX IF NOT EXISTS idx_activities_lead_id ON activities(lead_id);
\nCREATE INDEX IF NOT EXISTS idx_activities_created_by ON activities(created_by);
;
